#' Decision Curve Analysis (Python)
#'
#' 
#' @param data .
#' @param outcome .
#' @param models .
#' @param positive .
#' @param thresholdMin .
#' @param thresholdMax .
#' @param thresholdStep .
#' @param showPlot .
#' @param showConsole .
#' @return A results object containing:
#' \tabular{llllll}{
#'   \code{results$summary} \tab \tab \tab \tab \tab a text \cr
#'   \code{results$cohort} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$curves} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$netBenefitPlot} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$console} \tab \tab \tab \tab \tab a preformatted \cr
#' }
#'
#' Tables can be converted to data frames with \code{asDF} or \code{\link{as.data.frame}}. For example:
#'
#' \code{results$cohort$asDF}
#'
#' \code{as.data.frame(results$cohort)}
#'
#' @export
pydecisioncurve <- function(
    data,
    outcome = NULL,
    models = NULL,
    positive,
    thresholdMin = 0.05,
    thresholdMax = 0.5,
    thresholdStep = 0.01,
    showPlot = TRUE,
    showConsole = FALSE) {

    if ( ! requireNamespace("jmvcore", quietly=TRUE))
        stop("pydecisioncurve requires jmvcore to be installed (restart may be required)")

    if ( ! missing(outcome)) outcome <- jmvcore::resolveQuo(jmvcore::enquo(outcome))
    if ( ! missing(models)) models <- jmvcore::resolveQuo(jmvcore::enquo(models))
    if (missing(data))
        data <- jmvcore::marshalData(
            parent.frame(),
            `if`( ! missing(outcome), outcome, NULL),
            `if`( ! missing(models), models, NULL))

    for (v in outcome) if (v %in% names(data)) data[[v]] <- as.factor(data[[v]])

    options <- pydecisioncurveOptions$new(
        outcome = outcome,
        models = models,
        positive = positive,
        thresholdMin = thresholdMin,
        thresholdMax = thresholdMax,
        thresholdStep = thresholdStep,
        showPlot = showPlot,
        showConsole = showConsole)

    analysis <- pydecisioncurveClass$new(
        options = options,
        data = data)

    analysis$run()

    analysis$results
}

